{
  "root_cause": "The accessible-autocomplete library's enhanceSelectElement only updates the underlying select element when the confirmed text matches an option. If the user enters unrecognized text or clears the field and confirms (via Enter or blur), the previous selection remains. Additionally, pressing Enter to submit the form does not trigger the library's confirmation logic, so the select elements are not synced with the combobox inputs.",
  "repair_strategy": "Provide a custom onConfirm handler for each enhanced select that explicitly clears the selection (sets the empty option) when the confirmed text does not match any option. Also add a form submit listener that reads the combobox input values and updates the hidden select elements accordingly, ensuring the saved data reflects what is visible at the moment of submission.",
  "edits": [
    {
      "path": "app.js",
      "sha256": "c30f79b8979a8d326c48de077074e081c30011f726524bcb32383da7074ce489",
      "before": "for(const id of ['shipping-country','billing-country'])accessibleAutocomplete.enhanceSelectElement({selectElement:document.getElementById(id)});
document.getElementById('preferences').addEventListener('submit',event=>event.preventDefault());
accessibleAutocomplete({element:document.getElementById('destination-field'),id:'destination',name:'destination',source:['Paris','Lyon','Berlin','Rome']});
document.getElementById('search').addEventListener('submit',event=>event.preventDefault());",
      "after": "for (const id of ['shipping-country','billing-country']) {
  const select = document.getElementById(id);
  accessibleAutocomplete.enhanceSelectElement({
    selectElement: select,
    onConfirm: function(text) {
      const options = select.options;
      let found = false;
      for (let i = 0; i < options.length; i++) {
        if (options[i].textContent === text) {
          options[i].selected = true;
          found = true;
          break;
        }
      }
      if (!found) {
        for (let i = 0; i < options.length; i++) {
          if (options[i].value === "") {
            options[i].selected = true;
            break;
          }
        }
      }
    }
  });
}

function updateSelectFromCombobox(comboboxId) {
  const input = document.getElementById(comboboxId);
  const select = document.getElementById(comboboxId + '-select');
  if (!input || !select) return;
  const value = input.value;
  let found = false;
  for (let i = 0; i < select.options.length; i++) {
    if (select.options[i].textContent === value) {
      select.options[i].selected = true;
      found = true;
      break;
    }
  }
  if (!found) {
    for (let i = 0; i < select.options.length; i++) {
      if (select.options[i].value === "") {
        select.options[i].selected = true;
        break;
      }
    }
  }
}

document.getElementById('preferences').addEventListener('submit', function(event) {
  event.preventDefault();
  updateSelectFromCombobox('shipping-country');
  updateSelectFromCombobox('billing-country');
});

accessibleAutocomplete({element:document.getElementById('destination-field'),id:'destination',name:'destination',source:['Paris','Lyon','Berlin','Rome']});
